func TestValidateRejectsReservedExampleTargets(t *testing.T) {
	tests := []string{
		"https://example.com/health",
		"https://api.example.net/health",
		"https://EXAMPLE.ORG./health",
	}
	for _, targetURL := range tests {
		t.Run(targetURL, func(t *testing.T) {
			profile := validProfileForValidation(targetURL)
			err := profile.Validate()
			if err == nil {
				t.Fatal("Validate accepted a reserved example target")
			}
			if !strings.Contains(err.Error(), "documentation placeholders") {
				t.Errorf("Validate error %q does not explain the placeholder", err)
			}
		})
	}
}

