func TestLoadFileRejectsUnknownFieldsAndMultipleDocuments(test *testing.T) {
	tests := []struct {
		name    string
		content string
		wantErr string
	}{
		{name: "unknown root field", content: "version: 1\nmaxCost: 10\n", wantErr: "field maxCost"},
		{name: "unknown nested field", content: "version: 1\nfleet:\n  maxVMCounts: 10\n", wantErr: "field maxVMCounts"},
		{name: "extra document", content: "version: 1\n---\nversion: 1\n", wantErr: "exactly one YAML document"},
		{name: "single document", content: "version: 1\n# trailing comment\n"},
	}
	for _, testCase := range tests {
		test.Run(testCase.name, func(test *testing.T) {
			path := filepath.Join(test.TempDir(), "profile.yaml")
			if err := os.WriteFile(path, []byte(testCase.content), 0600); err != nil {
				test.Fatal(err)
			}
			profile, err := LoadFile(path)
			if testCase.wantErr != "" {
				if err == nil || !strings.Contains(err.Error(), testCase.wantErr) {
					test.Fatalf("got %v, want error containing %q", err, testCase.wantErr)
				}
				return
			}
			if err != nil || profile.Version != 1 {
				test.Fatalf("single YAML document rejected: %v", err)
			}
		})
	}
}
